pub struct Vault { store: Store, policy: Policy }   // fields private to this module

impl Vault {
    pub fn read(&self, subject: &Subject, id: Id) -> Result<Record, Denied> {
        self.policy.check(subject, id)?;            // every exported path passes here
        Ok(self.store.get(id))
    }
}
